/*
 * tb_token_selector_cosim_v4.cpp - dedicated C/RTL co-simulation testbench for
 * the packed v4 token selector (`token_selector_top_packed`).
 *
 * This testbench is deliberately INDEPENDENT of the 184-case g++ differential
 * bench: it replays exactly three representative frozen cases generated by
 * `tools/generate_cosim_v4_fixtures.py` from the reference
 * `evaluation/hardware_regular_selector_fixedpoint.py`.
 *
 *   1. cosim_identity_4x4_K48          - small identity bypass.
 *   2. cosim_16x16_K64_alltie          - context path, every score tied.
 *   3. cosim_32x32_K96_mixedextreme    - context path, saturated int8 tokens,
 *                                        score extremes 0 / 32767.
 *
 * For each case it verifies status, output_count / real_count / context_count,
 * scale_out, every token byte and every metadata byte (group_index,
 * source_type, region_id, valid), plus the ascending-unique representative
 * invariant.  The fixture directory (containing manifest.txt) is argv[1].
 *
 * The testbench is written with plain C strings/buffers (no std::string) so the
 * Vitis HLS `xilinx-tb-process` instrumentation reliably rewrites the
 * `token_selector_top_packed` call into the RTL co-simulation stub.
 *
 * Usage: tb_token_selector_cosim_v4 <fixture_dir>
 */
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include <vector>

#include "token_selector_hls.h"

namespace {

int failures = 0;
int passes = 0;

bool read_file(const char* path, std::vector<uint8_t>* data) {
  FILE* handle = fopen(path, "rb");
  if (handle == NULL) {
    return false;
  }
  if (fseek(handle, 0, SEEK_END) != 0) {
    fclose(handle);
    return false;
  }
  long size = ftell(handle);
  if (size < 0) {
    fclose(handle);
    return false;
  }
  if (fseek(handle, 0, SEEK_SET) != 0) {
    fclose(handle);
    return false;
  }
  data->resize(static_cast<size_t>(size));
  if (size > 0) {
    size_t got = fread(data->data(), 1, static_cast<size_t>(size), handle);
    if (got != static_cast<size_t>(size)) {
      fclose(handle);
      return false;
    }
  }
  fclose(handle);
  return true;
}

bool take_bytes(const std::vector<uint8_t>& data, size_t* offset, void* out,
                size_t size) {
  if (*offset + size > data.size()) {
    return false;
  }
  memcpy(out, data.data() + *offset, size);
  *offset += size;
  return true;
}

bool take_i32(const std::vector<uint8_t>& data, size_t* offset, int* out) {
  int32_t value = 0;
  if (!take_bytes(data, offset, &value, sizeof(value))) {
    return false;
  }
  *out = static_cast<int>(value);
  return true;
}

bool take_f32(const std::vector<uint8_t>& data, size_t* offset, float* out) {
  return take_bytes(data, offset, out, sizeof(float));
}

void report(const char* name, bool ok, const char* detail) {
  if (ok) {
    passes += 1;
    printf("[COSIM-PASS] %s\n", name);
  } else {
    failures += 1;
    printf("[COSIM-FAIL] %s : %s\n", name, detail);
  }
}

bool run_case(const char* fixture_dir, const char* name, int group_count,
              int grid_h, int grid_w, int budget, int local_cap) {
  char path[1024];
  snprintf(path, sizeof(path), "%s/%s.in.bin", fixture_dir, name);
  std::vector<uint8_t> input;
  if (!read_file(path, &input) || input.size() < 4 ||
      memcmp(input.data(), "TSIN", 4) != 0) {
    report(name, false, "cannot read input fixture");
    return false;
  }
  size_t in_offset = 4;
  int in_g = 0, in_gh = 0, in_gw = 0, in_budget = 0, in_cap = 0;
  float in_scale = 0.0f;
  if (!take_i32(input, &in_offset, &in_g) ||
      !take_i32(input, &in_offset, &in_gh) ||
      !take_i32(input, &in_offset, &in_gw) ||
      !take_i32(input, &in_offset, &in_budget) ||
      !take_i32(input, &in_offset, &in_cap) ||
      !take_f32(input, &in_offset, &in_scale)) {
    report(name, false, "malformed input header");
    return false;
  }
  if (in_g != group_count || in_gh != grid_h || in_gw != grid_w ||
      in_budget != budget || in_cap != local_cap) {
    report(name, false, "input header mismatches manifest");
    return false;
  }
  std::vector<int8_t> tokens_q(static_cast<size_t>(group_count) * TS_GROUP_ELEMENTS);
  std::vector<uint16_t> score_q(static_cast<size_t>(TS_MAX_GROUPS), 0);
  if (!take_bytes(input, &in_offset, tokens_q.data(),
                  tokens_q.size() * sizeof(int8_t)) ||
      !take_bytes(input, &in_offset, score_q.data(),
                  static_cast<size_t>(group_count) * sizeof(uint16_t))) {
    report(name, false, "malformed input payload");
    return false;
  }

  /*
   * The cosim wrapper dumps the whole declared m_axi port depth, so the host
   * buffers must span that full depth (words for the token ports, elements for
   * the scalar/metadata ports); the unused tail stays zero.
   */
  std::vector<uint8_t> tokens_bytes(
      static_cast<size_t>(TS_MAX_WORDS) * TS_WORD_BYTES, 0);
  ts_word_t* tokens_words = reinterpret_cast<ts_word_t*>(tokens_bytes.data());
  ts_pack_int8_to_words(tokens_q.data(), static_cast<int>(tokens_q.size()),
                        tokens_words, group_count * TS_GROUP_WORDS);

  snprintf(path, sizeof(path), "%s/%s.exp.bin", fixture_dir, name);
  std::vector<uint8_t> expected;
  if (!read_file(path, &expected) || expected.size() < 4 ||
      memcmp(expected.data(), "TSEX", 4) != 0) {
    report(name, false, "cannot read expected fixture");
    return false;
  }
  size_t exp_offset = 4;
  int exp_status = 0, exp_out = 0, exp_real = 0, exp_ctx = 0;
  float exp_scale = 0.0f;
  if (!take_i32(expected, &exp_offset, &exp_status) ||
      !take_i32(expected, &exp_offset, &exp_out) ||
      !take_i32(expected, &exp_offset, &exp_real) ||
      !take_i32(expected, &exp_offset, &exp_ctx) ||
      !take_f32(expected, &exp_offset, &exp_scale)) {
    report(name, false, "malformed expected header");
    return false;
  }

  std::vector<uint8_t> out_tokens_bytes(
      static_cast<size_t>(TS_MAX_WORDS) * TS_WORD_BYTES, 0);
  ts_word_t* out_tokens_words =
      reinterpret_cast<ts_word_t*>(out_tokens_bytes.data());
  std::vector<uint16_t> out_group_index(static_cast<size_t>(TS_MAX_GROUPS), 0);
  std::vector<uint8_t> out_source_type(static_cast<size_t>(TS_MAX_GROUPS), 0);
  std::vector<uint8_t> out_region_id(static_cast<size_t>(TS_MAX_GROUPS), 0);
  std::vector<uint8_t> out_valid(static_cast<size_t>(TS_MAX_GROUPS), 0);
  float scale_out = 0.0f;
  int output_count = -1, real_count = -1, context_count = -1;
  int status = token_selector_top_packed(
      tokens_words, score_q.data(), out_tokens_words,
      out_group_index.data(), out_source_type.data(), out_region_id.data(),
      out_valid.data(), group_count, grid_h, grid_w, budget, local_cap, in_scale,
      &scale_out, &output_count, &real_count, &context_count);

  const char* detail = "";
  bool ok = true;
  if (status != exp_status) {
    ok = false;
    detail = "status mismatch";
  } else if (output_count != exp_out || real_count != exp_real ||
             context_count != exp_ctx) {
    ok = false;
    detail = "count mismatch";
  } else if (memcmp(&scale_out, &exp_scale, sizeof(float)) != 0) {
    ok = false;
    detail = "scale_out mismatch";
  } else if (status == TS_STATUS_OK) {
    size_t token_bytes = static_cast<size_t>(exp_out) * TS_GROUP_ELEMENTS;
    size_t index_bytes = static_cast<size_t>(exp_out) * sizeof(uint16_t);
    size_t meta_bytes = static_cast<size_t>(exp_out);
    size_t needed = exp_offset + token_bytes + index_bytes + 3 * meta_bytes;
    if (expected.size() < needed) {
      ok = false;
      detail = "expected payload too short";
    } else {
      std::vector<int8_t> unpacked(token_bytes);
      ts_unpack_words_to_int8(out_tokens_words, exp_out * TS_GROUP_WORDS,
                              unpacked.data(), static_cast<int>(token_bytes));
      const uint8_t* base = expected.data() + exp_offset;
      if (memcmp(unpacked.data(), base, token_bytes) != 0) {
        ok = false;
        detail = "token bytes mismatch";
      } else if (memcmp(out_group_index.data(), base + token_bytes,
                        index_bytes) != 0) {
        ok = false;
        detail = "group_index mismatch";
      } else if (memcmp(out_source_type.data(), base + token_bytes + index_bytes,
                        meta_bytes) != 0) {
        ok = false;
        detail = "source_type mismatch";
      } else if (memcmp(out_region_id.data(),
                        base + token_bytes + index_bytes + meta_bytes,
                        meta_bytes) != 0) {
        ok = false;
        detail = "region_id mismatch";
      } else if (memcmp(out_valid.data(),
                        base + token_bytes + index_bytes + 2 * meta_bytes,
                        meta_bytes) != 0) {
        ok = false;
        detail = "valid mismatch";
      } else {
        for (int i = 0; i < exp_out; i++) {
          if (out_valid[i] != 1) {
            ok = false;
            detail = "valid contains false";
            break;
          }
        }
        if (ok && exp_out > 1) {
          for (int i = 1; i < exp_out; i++) {
            if (out_group_index[i] <= out_group_index[i - 1]) {
              ok = false;
              detail = "group_index not strictly ascending/unique";
              break;
            }
          }
        }
      }
    }
  }
  report(name, ok, detail);
  return ok;
}

}  // namespace

int main(int argc, char** argv) {
  if (argc < 2) {
    fprintf(stderr, "usage: %s <fixture_dir>\n", argv[0]);
    return 2;
  }
  const char* fixture_dir = argv[1];
  char manifest_path[1024];
  snprintf(manifest_path, sizeof(manifest_path), "%s/manifest.txt", fixture_dir);
  FILE* manifest = fopen(manifest_path, "r");
  if (manifest == NULL) {
    fprintf(stderr, "cannot open %s\n", manifest_path);
    return 2;
  }

  char line[512];
  while (fgets(line, sizeof(line), manifest) != NULL) {
    char name[256];
    int group_count = 0, grid_h = 0, grid_w = 0, budget = 0, local_cap = 0;
    if (sscanf(line, "%255s %d %d %d %d %d", name, &group_count, &grid_h, &grid_w,
               &budget, &local_cap) != 6) {
      continue;
    }
    run_case(fixture_dir, name, group_count, grid_h, grid_w, budget, local_cap);
  }
  fclose(manifest);

  printf("TB token_selector_cosim_v4: passed=%d failed=%d\n", passes, failures);
  return failures == 0 ? 0 : 1;
}
